  "ak_4": "Escaner de red de codigo abierto para Windows",
  "ak_kn": "Bloc de notas cifrado de codigo abierto para Windows",
  "t_nav_stack": "Pila tecnologica",
  "t_nav_install": "Instalacion y datos",
